def E_pl(ko, pis, td, lew, kon, mn=0.0, psl=0.5, korona=0.22):
    # результат Сейма 2023 по воеводству: KO, ПиС, «Третий путь» (доля ПСЛ — psl), Левица (в т.ч. Razem), Конфедерация (в т.ч. Браун)
    oth = max(0.3, 100.0 - ko - pis - td - lew - kon - mn)
    return [ko, lew * 0.8, pis, td * (1 - psl), td * psl, lew * 0.2, oth, kon * korona, mn, kon * (1 - korona)]

